class FnMainShareInput(_FnMainShareInputRequired, _FnMainShareInputOptional):
    """The input of main/share."""


class FnMainShareOpenInput(TypedDict):
    """The input of main/share-open."""
    token: str


class _FnMainTeamPlanInputRequired(TypedDict):
    org: str


class _FnMainTeamPlanInputOptional(TypedDict, total=False):
    plan: Literal["free", "pro"]
    #: The team's IANA time zone, for its dashboard's months.
    timezone: str


class FnMainTeamPlanInput(_FnMainTeamPlanInputRequired, _FnMainTeamPlanInputOptional):
    """The input of main/team-plan."""


class _FnMainTeamPlanOutputRequired(TypedDict):
    org: str


class _FnMainTeamPlanOutputOptional(TypedDict, total=False):
    plan: str
    timezone: str


class FnMainTeamPlanOutput(_FnMainTeamPlanOutputRequired, _FnMainTeamPlanOutputOptional):
    """The output of main/team-plan."""


class FnMainThankSubmitterDoc(TypedDict):
    id: str
    version: int


class _FnMainThankSubmitterInputRequired(TypedDict):
    doc: FnMainThankSubmitterDoc
    event: Literal["created", "updated", "removed"]
    #: The change's id: the same on every delivery of it.
    id: str


class _FnMainThankSubmitterInputOptional(TypedDict, total=False):
    after: dict[str, Any] | None
    at: str
    before: dict[str, Any] | None
    #: The user who wrote, with `session: true` and when a user did.
    by: str
    changed: list[str]
    collection: str
    #: How deep in a chain of trigger runs this is: 0 for a change nobody's trigger made.
    depth: int
    root: str
    truncated: bool
    version: int


class FnMainThankSubmitterInput(_FnMainThankSubmitterInputRequired, _FnMainThankSubmitterInputOptional):
    """The input of main/thank-submitter."""


class ShelfConfigFeaturesExport(TypedDict, total=False):
    #: Members may export their assets
    enabled: bool


class ShelfConfigFeatures(TypedDict, total=False):
    export: ShelfConfigFeaturesExport


class ShelfConfigMaintenance(TypedDict, total=False):
    #: Show the banner
    enabled: bool
    message: str


class ShelfConfigTree(TypedDict, total=False):
    """The realm's app configuration."""
    features: ShelfConfigFeatures
    maintenance: ShelfConfigMaintenance


class ShelfConfigPath:
    """The app configuration's leaf paths, for client.config.get."""

    FEATURES_EXPORT_ENABLED = "features.export.enabled"
    MAINTENANCE_ENABLED = "maintenance.enabled"
    MAINTENANCE_MESSAGE = "maintenance.message"


class ShelfRoles:
    """The roles "shelf" declares."""

    ADMIN = "admin"
