class ShelfMail:
    """The "mail" database of "shelf", typed."""

    def __init__(self, db: backd.Database) -> None:
        self.db = db

    @property
    def outbox(self) -> backd.Collection[MailOutbox]:
        """The "outbox" collection: documents read as MailOutbox."""
        return self.db.collection("outbox", MailOutbox)


class ShelfMain:
    """The "main" database of "shelf", typed."""

    def __init__(self, db: backd.Database) -> None:
        self.db = db

    @property
    def assets(self) -> backd.Collection[MainAssets]:
        """The "assets" collection: documents read as MainAssets."""
        return self.db.collection("assets", MainAssets)

    @property
    def imports(self) -> backd.Collection[MainImports]:
        """The "imports" collection: documents read as MainImports."""
        return self.db.collection("imports", MainImports)

    @property
    def members(self) -> backd.Collection[MainMembers]:
        """The "members" collection: documents read as MainMembers."""
        return self.db.collection("members", MainMembers)

    @property
    def notifications(self) -> backd.Collection[MainNotifications]:
        """The "notifications" collection: documents read as MainNotifications."""
        return self.db.collection("notifications", MainNotifications)

    @property
    def pins(self) -> backd.Collection[MainPins]:
        """The "pins" collection: documents read as MainPins."""
        return self.db.collection("pins", MainPins)

    @property
    def profiles(self) -> backd.Collection[MainProfiles]:
        """The "profiles" collection: documents read as MainProfiles."""
        return self.db.collection("profiles", MainProfiles)

    @property
    def shares(self) -> backd.Collection[MainShares]:
        """The "shares" collection: documents read as MainShares."""
        return self.db.collection("shares", MainShares)

    @property
    def submissions(self) -> backd.Collection[MainSubmissions]:
        """The "submissions" collection: documents read as MainSubmissions."""
        return self.db.collection("submissions", MainSubmissions)

    def digest(self, input: FnMainDigestInput) -> backd.Job:
        """Calls main/digest (async: it answers a job; wait() for the output)."""
        return cast(backd.Job, self.db.fn("digest", input))

    def download(self, input: FnMainDownloadInput) -> Any:
        """Calls main/download."""
        return cast(Any, self.db.fn("download", input))

    def export(self, input: Any = None) -> Any:
        """Calls main/export."""
        return cast(Any, self.db.fn("export", input))

    def import_(self, input: Any = None) -> Any:
        """Calls main/import."""
        return cast(Any, self.db.fn("import", input))

    def pin(self, input: FnMainPinInput) -> FnMainPinOutput:
        """Calls main/pin."""
        return cast(FnMainPinOutput, self.db.fn("pin", input))

    def preview(self, input: FnMainPreviewInput) -> Any:
        """Calls main/preview."""
        return cast(Any, self.db.fn("preview", input))

    def publish(self, input: FnMainPublishInput) -> Any:
        """Calls main/publish."""
        return cast(Any, self.db.fn("publish", input))

    def share(self, input: FnMainShareInput) -> Any:
        """Calls main/share."""
        return cast(Any, self.db.fn("share", input))

    def share_open(self, input: FnMainShareOpenInput) -> Any:
        """Calls main/share-open."""
        return cast(Any, self.db.fn("share-open", input))

    def team_plan(self, input: FnMainTeamPlanInput) -> FnMainTeamPlanOutput:
        """Calls main/team-plan."""
        return cast(FnMainTeamPlanOutput, self.db.fn("team-plan", input))


class ShelfRealm:
    """The "shelf" realm bound to a client: its databases, collections and functions, typed."""

    def __init__(self, client: backd.Client) -> None:
        self.client = client

    @property
    def mail(self) -> ShelfMail:
        """The "mail" database."""
        return ShelfMail(self.client.db("mail"))

    @property
    def main(self) -> ShelfMain:
        """The "main" database."""
        return ShelfMain(self.client.db("main"))

    def load_config(self) -> ShelfConfigTree:
        """Reads the realm's app configuration, as the caller sees it."""
        return cast(ShelfConfigTree, self.client.config.load())


